            assert(exp.op === EXP.concatenateAssign);
            // `ref Loc loc` (dmd/expressionsem.d:3553) — a REBINDABLE alias to the field, so
            // the in/out box reads and writes `exp.e1!.loc` in place (03 §3.2/§7.2; the tree's
            // precedent shape, dcast.ts:3021). NOT a copy: `Loc` is an ALIAS-SAFE REGISTER
            // member (03 §9.1).
            const locRef: Ref<Loc> = {
                get value(): Loc { return exp.e1!.loc; },
                set value(v: Loc) { exp.e1!.loc = v; },
            };
